const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
const idSet = new Set();

const designs = T.map((row, i) => {
  const [category, style, city, property, tier, title, summary, elements, materials, area] = row;
  let id = slug(title);
  while (idSet.has(id)) id += '-2';
  idSet.add(id);
  const areaSqft = area ?? DEFAULT_AREAS[category] ?? 150;
  const est = estimate({ city, property, finish: tier, rooms: [{ type: category, areaSqft }] });
  return {
    id,
    title,
    summary,
    category,
    style,
    city,
    climate: cityClimate[city],
    property,
    budgetTier: tier,
    budget: { low: est.low, high: est.high, basis: `Indicative model estimate for about ${areaSqft} sq ft, ${tier} finish (not a quotation)` },
    areaSqft,
    elements,
    materials,
    images: [0, 1, 2].map((n) => ({
      src: `assets/illustrations/designs/${id}-${n + 1}.svg`,
      width: 1200,
      height: 900,
      view: ['room', 'detail', 'corner'][n],
      alt: altFor(n, title, category, style),
    })),
    credit: 'Original vector illustration generated for Nivasa (demonstration).',
    license: 'Project-original artwork; reuse under the repository licence.',
    demo: true,
    featured: [0, 2, 5, 16, 26, 36, 44, 57].includes(i),
    added: `2026-10-${String(1 + (i % 28)).padStart(2, '0')}`,
    popularity: (i * 37) % 100,
  };
});

function altFor(n, title, category, style) {
  const room = categories.groups.flatMap((g) => g.items).find((x) => x.id === category)?.name ?? category;
  const st = categories.groups.find((g) => g.id === 'styles').items.find((x) => x.id === style)?.name ?? style;
  if (n === 0) return `Illustration of ${title.toLowerCase()}: a ${st.toLowerCase()} ${room.toLowerCase()} seen from the doorway.`;
  if (n === 1) return `Close-up illustration of materials and details from ${title.toLowerCase()}.`;
  return `Corner view illustration of the ${room.toLowerCase()} in ${st.toLowerCase()} style.`;
}

