writeFileSync(new URL('../src/data/designs.json', import.meta.url), JSON.stringify({ version: 1, demo: true, note: 'Demonstration catalogue. All designs are fictional concepts illustrated with original generated vector art, not photographs of real projects. Budgets are indicative model estimates, not quotations.', designs }, null, 2) + '\n');
